import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { MNEMONICS, packRadix40 } from "./abi.mjs";

const entries = MNEMONICS.flatMap((name, ordinal) => {
  if (name === null) return [];
  const [first, second] = packRadix40(name);
  return [{ name, ordinal, first, second }];
}).sort((left, right) => left.first - right.first || left.second - right.second);

const lines = [
  "; Generated by src/generate-mnemonics.mjs. Do not edit.",
  `ZapMnemonicCount: .equ ${entries.length}`,
  "ZapMnemonicTable:",
  ...entries.flatMap(({ name, ordinal, first, second }) => [
    `            .dw  $${first.toString(16).padStart(4, "0").toUpperCase()},$${second.toString(16).padStart(4, "0").toUpperCase()}`,
    `            .db  ${ordinal} ; ${name}`,
  ]),
  "ZapMnemonicTableEnd:",
  "",
];

const target = fileURLToPath(new URL("../asm/zap-mnemonics.inc", import.meta.url));
writeFileSync(target, lines.join("\n"));
